/* @lc app=leetcode id=3608 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = generateSequence(x) { if (p[it] == it) null else p[it] }.toList().let { path -> path.last().also { r -> path.forEach { p[it] = r } } } fun cc(n: Int, edges: Array<IntArray>, t: Int): Int = IntArray(n) { it }.let { p -> edges.filter { it[2] > t }.count { e -> (find(p, e[0]) != find(p, e[1])).also { d -> if (d) p[find(p, e[0])] = find(p, e[1]) } }.let { n - it } } fun minTime(n: Int, edges: Array<IntArray>, k: Int): Int = generateSequence(0 to 1_000_000_000) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { mid -> if (cc(n, edges, mid) >= k) lo to mid else mid + 1 to hi } }.last().first }